    @Test public void manualExportWritesExactCopyThroughAndroidProvider()throws Exception{
        File source=nativePdf("manual-export-source.pdf",2);ContentValues values=new ContentValues();values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,"paperflow-qa-"+System.nanoTime()+".pdf");values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"application/pdf");values.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/PaperFlow-QA");
        android.net.Uri uri=c.getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);assertNotNull(uri);Activity a=null;
        try{a=inst.startActivitySync(new Intent(c,CloudExportActivity.class).putStringArrayListExtra("paths",new ArrayList<>(Collections.singletonList(source.getPath()))).putStringArrayListExtra("names",new ArrayList<>(Collections.singletonList("QA export"))).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity active=a;
            inst.runOnMainSync(()->{try{invoke(active,"write",new Class<?>[]{android.net.Uri.class,boolean.class},uri,false);}catch(Exception e){throw new RuntimeException(e);}});long end=SystemClock.elapsedRealtime()+20000;while((Boolean)field(a,"busy")&&SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertFalse((Boolean)field(a,"busy"));
            try(InputStream in=c.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);assertArrayEquals(bytes(source),out.toByteArray());}
            json("manual-export.json",new JSONObject().put("androidContentProvider",true).put("exactBytes",true).put("cloudNetworkVerified",false));
        }finally{if(a!=null){Activity active=a;inst.runOnMainSync(active::finish);}c.getContentResolver().delete(uri,null,null);}
    }
    @Test public void independentlyAuthoredOfficeFilesImport()throws Exception{
        String[] types={"docx","xlsx","pptx"};
        for(String type:types){File input=new File(dir,"external-input."+type);try(InputStream in=inst.getContext().getAssets().open("office-fixtures/external."+type);OutputStream out=new FileOutputStream(input)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}File out=new File(dir,"external-"+type+".pdf");OfficeImport.convert(input,out,(a,b)->{});try(PDDocument doc=PDDocument.load(out)){assertTrue(doc.getNumberOfPages()>0);String text=new PDFTextStripper().getText(doc);assertTrue(type+": "+text,text.contains("Invoice"));if(!type.equals("pptx"))assertTrue(text,text.contains("Paper"));Bitmap preview=PdfLayout.render(doc,0,600,800);image("external-"+type+".png",preview);preview.recycle();}}
        json("external-office.json",new JSONObject().put("independentInputs",3).put("textRetained",true));
    }
    @SuppressWarnings("unchecked") @Test public void pdfEditAnnotationsReplacementAndRedaction()throws Exception{
        File source=nativePdf("editing-source.pdf",2);byte[] original=bytes(source);
        for(String tool:new String[]{"Highlight","Replace text","Redact"}){
            File documents=new File(c.getFilesDir(),"documents");documents.mkdirs();Set<String> before=new HashSet<>(Arrays.asList(documents.list()));
            Activity a=inst.startActivitySync(new Intent(c,PdfEditActivity.class).putExtra("path",source.getPath()).putExtra("name","QA edit").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_MULTIPLE_TASK));
            File created=null;Instrumentation.ActivityMonitor viewerMonitor=inst.addMonitor(PdfViewerActivity.class.getName(),null,false);
            try{long end=SystemClock.elapsedRealtime()+30000;while((Boolean)field(a,"busy")&&SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertFalse((Boolean)field(a,"busy"));
                PdfEditActivity.Mark mark=new PdfEditActivity.Mark();mark.page=0;mark.tool=tool;mark.text="REPLACED CONTENT";mark.bounds.set(.05f,.02f,.7f,.12f);ArrayList<PdfEditActivity.Mark> marks=(ArrayList<PdfEditActivity.Mark>)field(a,"marks");inst.runOnMainSync(()->marks.add(mark));
                inst.runOnMainSync(()->{try{invoke(a,"write",new Class<?>[]{boolean.class},tool.equals("Redact"));}catch(Exception e){throw new RuntimeException(e);}});
                end=SystemClock.elapsedRealtime()+60000;while(!a.isFinishing()&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);assertTrue("Export did not finish: "+tool,a.isFinishing());Activity viewer=inst.waitForMonitorWithTimeout(viewerMonitor,15000);assertNotNull("Edited copy did not open",viewer);inst.runOnMainSync(viewer::finish);inst.waitForIdleSync();
                for(File f:documents.listFiles())if(!before.contains(f.getName())&&f.getName().startsWith("paperflow-edit-")){created=f;break;}assertNotNull(created);
                try(PDDocument doc=PDDocument.load(created)){assertEquals(2,doc.getNumberOfPages());String text=new PDFTextStripper().getText(doc);if(tool.equals("Redact")){assertTrue(text.trim().isEmpty());for(PDPage page:doc.getPages())assertTrue(page.getAnnotations().isEmpty());assertNull(doc.getDocumentInformation().getTitle());Bitmap preview=PdfLayout.render(doc,0,600,800);assertEquals(Color.BLACK,preview.getPixel(100,40));preview.recycle();}else if(tool.equals("Replace text")){assertTrue(text,text.contains("REPLACED CONTENT"));assertFalse(text,text.contains("Invoice 1"));assertTrue(text,text.contains("Invoice 2"));}else{assertEquals(1,doc.getPage(0).getAnnotations().size());assertTrue(text,text.contains("Invoice 1"));}}
                try(InputStream in=new FileInputStream(created);OutputStream out=new FileOutputStream(new File(dir,"edit-"+tool.replace(' ','-')+".pdf"))){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}
            }finally{inst.removeMonitor(viewerMonitor);inst.runOnMainSync(a::finish);if(created!=null){try(DocumentStore store=new DocumentStore(c)){store.db().delete("docs","path=?",new String[]{created.getPath()});}created.delete();}}
        }
        assertArrayEquals(original,bytes(source));json("pdf-edit.json",new JSONObject().put("annotations",true).put("replacement",true).put("redaction",true).put("originalPreserved",true));
    }
    final Instrumentation inst=InstrumentationRegistry.getInstrumentation();Context c;File dir;Set<String> languages;
    @Before public void setup(){c=inst.getTargetContext();PDFBoxResourceLoader.init(c);dir=new File(c.getExternalFilesDir(null),"remaining-feature-tests");dir.mkdirs();languages=new HashSet<>(c.getSharedPreferences("local-languages",0).getStringSet("ocr-enabled",Collections.emptySet()));select();}
