    void select(String... codes){c.getSharedPreferences("local-languages",0).edit().putStringSet("ocr-enabled",new HashSet<>(Arrays.asList(codes))).commit();}
    Object field(Object owner,String name)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
    void set(Object owner,String name,Object value)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);f.set(owner,value);}
    Object invoke(Object owner,String name,Class<?>[] types,Object... values)throws Exception{Method m=owner.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(owner,values);}
    void json(String name,JSONObject value)throws Exception{try(OutputStream out=new FileOutputStream(new File(dir,name))){out.write(value.toString(2).getBytes(StandardCharsets.UTF_8));}}
    void image(String name,Bitmap bitmap)throws Exception{try(OutputStream out=new FileOutputStream(new File(dir,name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}}
    static void text(PDDocument d,PDPage p,String value,float x,float y,float size)throws Exception{try(PDPageContentStream stream=new PDPageContentStream(d,p,PDPageContentStream.AppendMode.APPEND,true,true)){stream.beginText();stream.setFont(PDType1Font.HELVETICA,size);stream.newLineAtOffset(x,y);stream.showText(value);stream.endText();}}
    File nativePdf(String name,int pages)throws Exception{File file=new File(dir,name);try(PDDocument d=new PDDocument()){for(int i=0;i<pages;i++){PDPage p=new PDPage(new PDRectangle(600,800));d.addPage(p);text(d,p,"Invoice "+(i+1),48,740,22);String[][] rows={{"Product","Qty","Price"},{"Paper","2","12.50"},{"Pens","5","3.25"},{"Reference","00123","TOTAL"}};for(int r=0;r<rows.length;r++)for(int k=0;k<3;k++)text(d,p,rows[r][k],48+k*180,660-r*45,14);Bitmap logo=Bitmap.createBitmap(100,60,Bitmap.Config.ARGB_8888);logo.eraseColor(0xff107ad8);try(PDPageContentStream s=new PDPageContentStream(d,p,PDPageContentStream.AppendMode.APPEND,true,true)){s.drawImage(JPEGFactory.createFromImage(d,logo),60,100,150,90);}logo.recycle();}d.save(file);}return file;}
    File rasterPdf(String name,String... labels)throws Exception{File file=new File(dir,name);try(PDDocument d=new PDDocument()){for(String label:labels){Bitmap image=Bitmap.createBitmap(1200,1600,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(Color.WHITE);Paint p=new Paint(3);p.setColor(Color.BLACK);p.setTextSize(90);canvas.drawText(label,90,230,p);p.setTextSize(52);canvas.drawText("Searchable document for PaperFlow",90,380,p);PDPage page=new PDPage(new PDRectangle(600,800));d.addPage(page);try(PDPageContentStream s=new PDPageContentStream(d,page)){s.drawImage(JPEGFactory.createFromImage(d,image,.95f),0,0,600,800);}image.recycle();}d.save(file);}return file;}
    byte[] bytes(File file)throws Exception{try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
    void installEnglish()throws Exception{JSONArray entries=LanguageModels.catalog(c,"ocr");for(int i=0;i<entries.length();i++){JSONObject pack=entries.getJSONObject(i);if(pack.getString("code").equals("eng")){if(!LanguageModels.installed(c,"ocr",pack))LanguageModels.download(c,"ocr",pack,()->false,(a,b)->{});select("eng");return;}}fail("English catalog entry missing");}
    void validateXml(File file)throws Exception{try(ZipFile zip=new ZipFile(file)){Enumeration<? extends ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){ZipEntry e=entries.nextElement();if(e.getName().endsWith(".xml")||e.getName().endsWith(".rels")){javax.xml.parsers.DocumentBuilderFactory f=javax.xml.parsers.DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);try(InputStream in=zip.getInputStream(e)){f.newDocumentBuilder().parse(in);}}}}}
    @Test public void officeExportsAndLocalImportsPreserveGeneratedContent()throws Exception{
        File source=nativePdf("office-source.pdf",2);JSONObject report=new JSONObject();
        for(boolean editable:new boolean[]{false,true}){
            String mode=editable?"editable":"appearance";File word=new File(dir,"office-"+mode+".docx"),ppt=new File(dir,"office-"+mode+".pptx");assertEquals(2,OfficeExport.word(c,source,"",word,editable,null,(a,b)->{}));assertEquals(2,OfficeExport.powerpoint(c,source,"",ppt,editable,null,(a,b)->{}));validateXml(word);validateXml(ppt);
            for(File office:new File[]{word,ppt}){File pdf=new File(dir,office.getName()+".pdf");int pages=OfficeImport.convert(office,pdf,(a,b)->{});assertEquals("Page count for "+office.getName(),2,pages);try(PDDocument doc=PDDocument.load(pdf)){assertEquals(2,doc.getNumberOfPages());Bitmap rendered=PdfLayout.render(doc,0,600,800);image(office.getName()+".png",rendered);int colored=0;for(int y=0;y<rendered.getHeight();y+=3)for(int x=0;x<rendered.getWidth();x+=3){int pixel=rendered.getPixel(x,y);if(Color.blue(pixel)>Color.red(pixel)+40)colored++;}assertTrue("Blue source graphic survives "+office.getName(),colored>300);rendered.recycle();if(editable){String text=new PDFTextStripper().getText(doc);assertTrue(office.getName()+": "+text,text.contains("Invoice"));}}}
            report.put(mode,true);
        }
        File xlsx=new File(dir,"office-table.xlsx");assertEquals(2,OfficeExport.excel(c,source,"",xlsx,null,(a,b)->{}));validateXml(xlsx);try(ZipFile z=new ZipFile(xlsx);InputStream in=z.getInputStream(z.getEntry("xl/worksheets/sheet1.xml"))){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] chunk=new byte[1024];int n;while((n=in.read(chunk))!=-1)b.write(chunk,0,n);String xml=b.toString("UTF-8");assertTrue(xml,xml.contains("Product"));assertTrue(xml,xml.contains("00123"));assertTrue(xml,xml.contains("<v>12.50</v>"));}
        File xpdf=new File(dir,"office-table.pdf");assertEquals(2,OfficeImport.convert(xlsx,xpdf,(a,b)->{}));try(PDDocument d=PDDocument.load(xpdf)){assertTrue(new PDFTextStripper().getText(d).contains("Product"));}File selected=new File(dir,"office-selected.xlsx");OfficeExport.excel(c,source,"",selected,Collections.singletonList(1),(a,b)->{});try(ZipFile z=new ZipFile(selected)){assertNull(z.getEntry("xl/worksheets/sheet2.xml"));}report.put("xlsx",true).put("selectedPages",true);json("office.json",report);
    }
    @Test public void officePackageRejectsDtdAndLegacyInput()throws Exception{File malicious=new File(dir,"bad-office.docx");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(malicious))){OfficePackage.entry(z,"word/document.xml","<!DOCTYPE x [<!ENTITY x SYSTEM 'file:///data/system/secret'>]><document>&x;</document>");}try{OfficeImport.convert(malicious,new File(dir,"bad.pdf"),(a,b)->{});fail("DTD accepted");}catch(IOException expected){assertTrue(expected.getMessage(),expected.getMessage().contains("declaration"));}File legacy=new File(dir,"legacy.doc");try(OutputStream out=new FileOutputStream(legacy)){out.write(new byte[]{1,2,3});}try{OfficeImport.convert(legacy,new File(dir,"legacy.pdf"),(a,b)->{});fail("Non-OOXML accepted");}catch(IOException expected){}json("office-input-validation.json",new JSONObject().put("dtdRejected",true).put("legacyRejected",true));}
    ExtendedToolsActivity activity(String operation){return (ExtendedToolsActivity)inst.startActivitySync(new Intent(c,ExtendedToolsActivity.class).putExtra("operation",operation).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
    void run(ExtendedToolsActivity a)throws Exception{inst.runOnMainSync(()->{try{invoke(a,"process",new Class<?>[0]);}catch(Exception e){throw new RuntimeException(e);}});long deadline=SystemClock.elapsedRealtime()+240000;while((boolean)field(a,"busy")&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(100);assertFalse("Tool timed out",(boolean)field(a,"busy"));assertNotNull("Tool result: "+((TextView)field(a,"status")).getText(),field(a,"result"));inst.waitForIdleSync();}
    @SuppressWarnings("unchecked") @Test public void batchOcrExportsOnlyEachDocumentsChosenPages()throws Exception{installEnglish();File first=rasterPdf("batch-first.pdf","ALPHA FIRST","BETA SELECTED","GAMMA LAST"),second=rasterPdf("batch-second.pdf","DELTA SELECTED","EPSILON LAST");byte[] beforeFirst=bytes(first),beforeSecond=bytes(second);ExtendedToolsActivity a=activity("Batch OCR");try{ArrayList<ExtendedToolsActivity.Source> inputs=(ArrayList<ExtendedToolsActivity.Source>)field(a,"sources");ExtendedToolsActivity.Source one=new ExtendedToolsActivity.Source(first.getPath(),"first.pdf"),two=new ExtendedToolsActivity.Source(second.getPath(),"second.pdf");one.count=3;one.pages=new ArrayList<>(Collections.singletonList(1));two.count=2;two.pages=new ArrayList<>(Collections.singletonList(0));inst.runOnMainSync(()->{inputs.add(one);inputs.add(two);});set(a,"batchFormat",2);run(a);File result=(File)field(a,"result");try(ZipFile zip=new ZipFile(result)){for(String[] item:new String[][]{{"001-first.pdf","BETA","ALPHA"},{"002-second.pdf","DELTA","EPSILON"}}){try(InputStream in=zip.getInputStream(zip.getEntry(item[0]));PDDocument d=PDDocument.load(in)){assertEquals(1,d.getNumberOfPages());String text=new PDFTextStripper().getText(d);assertTrue(text,text.contains(item[1]));assertFalse(text,text.contains(item[2]));}assertNotNull(zip.getEntry(item[0].replace(".pdf",".txt")));}}assertArrayEquals(beforeFirst,bytes(first));assertArrayEquals(beforeSecond,bytes(second));try(InputStream in=new FileInputStream(result);OutputStream out=new FileOutputStream(new File(dir,"batch-result.zip"))){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}json("batch-ocr.json",new JSONObject().put("documents",2).put("pagesPerOutput",1).put("sourcesUnchanged",true));}finally{inst.runOnMainSync(a::finish);}}
    @SuppressWarnings("unchecked") @Test public void collageFitsPhotosAndExportsAllFormats()throws Exception{int[] colors={Color.RED,Color.GREEN,Color.BLUE};ArrayList<File> images=new ArrayList<>();for(int i=0;i<3;i++){Bitmap b=Bitmap.createBitmap(i==1?400:200,i==1?200:400,Bitmap.Config.ARGB_8888);b.eraseColor(colors[i]);File f=new File(dir,"collage-source-"+i+".png");try(OutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();images.add(f);}ExtendedToolsActivity a=activity("Collage");try{ArrayList<ExtendedToolsActivity.Source> inputs=(ArrayList<ExtendedToolsActivity.Source>)field(a,"sources");inst.runOnMainSync(()->{for(File image:images)inputs.add(new ExtendedToolsActivity.Source(image.getPath(),image.getName()));});for(int format=0;format<3;format++){set(a,"format",format);set(a,"result",null);run(a);File result=(File)field(a,"result");Bitmap bitmap;if(format==0)try(PDDocument doc=PDDocument.load(result)){assertEquals(1,doc.getNumberOfPages());bitmap=PdfLayout.render(doc,0,595,842);}else bitmap=BitmapFactory.decodeFile(result.getPath());assertNotNull(bitmap);for(int i=0;i<3;i++){int x=(int)((i%2==0?.255f:.745f)*bitmap.getWidth()),y=(int)((i<2?.255f:.745f)*bitmap.getHeight());int pixel=bitmap.getPixel(x,y);assertTrue("Collage color "+i+" / format "+format,Math.abs(Color.red(pixel)-Color.red(colors[i]))<25&&Math.abs(Color.green(pixel)-Color.green(colors[i]))<25&&Math.abs(Color.blue(pixel)-Color.blue(colors[i]))<25);}assertEquals(Color.WHITE,bitmap.getPixel(2,2));image("collage-format-"+format+".png",bitmap);bitmap.recycle();}json("collage.json",new JSONObject().put("formats",3).put("photos",3).put("positionsAndAspect",true));}finally{inst.runOnMainSync(a::finish);}}
    Bitmap documentImage(boolean different){Bitmap b=Bitmap.createBitmap(1000,1400,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(Color.WHITE);Paint p=new Paint(3);p.setColor(Color.BLACK);p.setTextSize(different?64:48);for(int i=0;i<15;i++)canvas.drawText(different?"CHAPTER TWO - A NEW PAGE "+i:"PaperFlow document line number "+i,60,130+i*75,p);p.setColor(0xff107ad8);canvas.drawRect(different?500:65,1200,different?900:400,1320,p);return b;}
    @Test public void uvdocRunsLocallyWithoutDestroyingSource()throws Exception{Bitmap source=documentImage(false);int pixel=source.getPixel(70,1250);long started=SystemClock.elapsedRealtime();Bitmap flat=CurvedPaper.flatten(c,source,"qa-document");long elapsed=SystemClock.elapsedRealtime()-started;assertEquals(source.getWidth(),flat.getWidth());assertEquals(source.getHeight(),flat.getHeight());assertFalse(source.isRecycled());assertEquals(pixel,source.getPixel(70,1250));int dark=0;for(int y=0;y<flat.getHeight();y+=5)for(int x=0;x<flat.getWidth();x+=5)if(Color.red(flat.getPixel(x,y))<100)dark++;assertTrue("Warp must retain document ink",dark>100);Bitmap second=CurvedPaper.flatten(c,source,"qa-document");assertTrue("Cached grid must be deterministic",flat.sameAs(second));image("uvdoc-generated-before.png",source);image("uvdoc-generated-after.png",flat);Matrix turn=new Matrix();turn.postRotate(90);Bitmap landscape=Bitmap.createBitmap(source,0,0,source.getWidth(),source.getHeight(),turn,true),wide=CurvedPaper.flatten(c,landscape,"qa-landscape");assertEquals(landscape.getWidth(),wide.getWidth());assertEquals(landscape.getHeight(),wide.getHeight());image("uvdoc-landscape.png",wide);json("uvdoc.json",new JSONObject().put("portraitMs",elapsed).put("inkSamples",dark).put("landscape",true).put("sourcePreserved",true).put("qualityComparedWithCamScanner",false));source.recycle();flat.recycle();second.recycle();landscape.recycle();wide.recycle();CurvedPaper.release();}
    @Test public void bookTrackerRequiresChangedSettledPage()throws Exception{Bitmap one=documentImage(false),two=documentImage(true);float[] q={0,0,1,0,1,1,0,1};int[] old=BookPageTracker.frame(one,q),next=BookPageTracker.frame(two,q);BookPageTracker tracker=new BookPageTracker();tracker.accept(old);assertFalse(tracker.changed(old));int[] brighter=old.clone();for(int i=0;i<brighter.length;i++)brighter[i]=Math.min(255,brighter[i]+12);assertFalse("Brightness change is not a new page",tracker.changed(brighter));assertTrue("Different page fingerprint",tracker.changed(next));for(int i=0;i<12;i++)assertFalse("Unchanged page must not rearm",tracker.observe(old));int[] handA=old.clone(),handB=old.clone();for(int i=0;i<handA.length;i++){if(i%32<20)handA[i]=70;if(i%32>8)handB[i]=90;}tracker.observe(handA);tracker.observe(handB);boolean ready=false;for(int i=0;i<12;i++)ready|=tracker.observe(next);assertTrue("Motion followed by a changed settled page",ready);tracker.accept(next);for(int i=0;i<12;i++)assertFalse(tracker.observe(next));one.recycle();two.recycle();json("book-tracker.json",new JSONObject().put("duplicateSuppressed",true).put("exposureSuppressed",true).put("changedPageAccepted",true).put("physicalCameraTested",false));}
    @Test public void cleanupPreservesTextAndReducesColorNoise()throws Exception{Bitmap image=Bitmap.createBitmap(800,1000,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(Color.WHITE);Paint p=new Paint(3);p.setColor(Color.BLACK);p.setTextSize(70);canvas.drawText("KEEP THIS TEXT",100,400,p);Bitmap clean=ScanCleanup.apply(image,true,false);assertTrue("No skin: image must stay unchanged",image.sameAs(clean));if(clean!=image)clean.recycle();p.setColor(0xffc99074);canvas.drawOval(-25,600,85,800,p);int textPixel=image.getPixel(150,380);Bitmap fixed=ScanCleanup.apply(image,true,false);assertEquals(textPixel,fixed.getPixel(150,380));image("finger-before.png",image);image("finger-after.png",fixed);assertTrue("Edge finger should be repaired",Color.green(fixed.getPixel(25,700))>Color.green(image.getPixel(25,700))+30);if(fixed!=image)fixed.recycle();Bitmap stripes=Bitmap.createBitmap(300,300,Bitmap.Config.ARGB_8888);for(int y=0;y<300;y++)for(int x=0;x<300;x++)stripes.setPixel(x,y,x%2==0?Color.rgb(190,140,165):Color.rgb(155,158,130));Bitmap smooth=ScanCleanup.apply(stripes,false,true);int before=Math.abs(Color.red(stripes.getPixel(150,150))-Color.red(stripes.getPixel(151,150))),after=Math.abs(Color.red(smooth.getPixel(150,150))-Color.red(smooth.getPixel(151,150)));assertTrue("Chroma stripes should weaken",after<before/2);json("cleanup.json",new JSONObject().put("textPreserved",true).put("edgeSkinRepaired",true).put("stripeDifferenceBefore",before).put("stripeDifferenceAfter",after));image.recycle();stripes.recycle();smooth.recycle();}
    @Test public void compressionKeepsTextRotationAnnotationsAndShrinksPhotos()throws Exception{File source=nativePdf("compression-source.pdf",1),out=new File(dir,"compression-result.pdf");try(PDDocument d=PDDocument.load(source)){PDPage page=d.getPage(0);page.setRotation(90);PDAnnotationText note=new PDAnnotationText();note.setContents("Retained annotation");note.setRectangle(new PDRectangle(30,30,20,20));page.getAnnotations().add(note);Bitmap photo=Bitmap.createBitmap(2200,1600,Bitmap.Config.ARGB_8888);Random random=new Random(4);int[] row=new int[2200];for(int y=0;y<1600;y++){for(int x=0;x<2200;x++){int n=random.nextInt(30);row[x]=Color.rgb(160+n,180+n,200+n);}photo.setPixels(row,0,2200,0,y,2200,1);}try(PDPageContentStream stream=new PDPageContentStream(d,page,PDPageContentStream.AppendMode.APPEND,true,true)){ByteArrayOutputStream encoded=new ByteArrayOutputStream();photo.compress(Bitmap.CompressFormat.JPEG,100,encoded);stream.drawImage(JPEGFactory.createFromByteArray(d,encoded.toByteArray()),40,180,500,350);}photo.recycle();d.save(source);PdfCompression.images(d,1);d.save(out);}try(PDDocument d=PDDocument.load(out)){assertTrue(new PDFTextStripper().getText(d).contains("Invoice"));assertEquals(90,d.getPage(0).getRotation());assertEquals(1,d.getPage(0).getAnnotations().size());assertEquals("Retained annotation",d.getPage(0).getAnnotations().get(0).getContents());}assertTrue("Eligible photo should shrink",out.length()<source.length());json("compression.json",new JSONObject().put("before",source.length()).put("after",out.length()).put("textRotationAnnotationsRetained",true));}
    ArrayList<EditText> edits(){ArrayList<EditText> values=new ArrayList<>();for(View root:android.view.inspector.WindowInspector.getGlobalWindowViews())collect(root,values);return values;}
    void collect(View view,ArrayList<EditText> values){if(view instanceof EditText&&view.isShown())values.add((EditText)view);if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)collect(group.getChildAt(i),values);}}
    void folderCall(String name,Activity a,long id,Runnable done){try{for(Method m:FolderLock.class.getDeclaredMethods())if(m.getName().equals(name)){m.setAccessible(true);m.invoke(null,a,id,done);return;}throw new NoSuchMethodException(name);}catch(Exception e){throw new RuntimeException(e);}}
    void awaitPinDialog(int minimumEdits){UiTestWait.until(()->{if(edits().size()<minimumEdits)return false;for(View root:android.view.inspector.WindowInspector.getGlobalWindowViews()){Button button=root.findViewById(android.R.id.button1);if(button!=null&&button.isShown()&&button.isEnabled())return true;}return false;},"PIN dialog did not become ready");}
    void positive(){for(View root:android.view.inspector.WindowInspector.getGlobalWindowViews()){Button button=root.findViewById(android.R.id.button1);if(button!=null&&button.isShown()&&button.isEnabled()){button.performClick();return;}}throw new AssertionError("Positive dialog button missing");}
    void waitUntil(java.util.function.BooleanSupplier predicate,long ms)throws Exception{long deadline=SystemClock.elapsedRealtime()+ms;while(!predicate.getAsBoolean()&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(50);assertTrue("Condition timed out",predicate.getAsBoolean());inst.waitForIdleSync();}
    @Test public void folderPinHidesDescendantsAndIndexesUntilUnlocked()throws Exception{File source=nativePdf("protected-source.pdf",1);Activity a=inst.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long folder,child,id;try(DocumentStore store=new DocumentStore(c)){ContentValues v=new ContentValues();v.put("name","QA protected "+System.nanoTime());folder=store.db().insertOrThrow("folders",null,v);v.put("parent",folder);v.put("name","QA child");child=store.db().insertOrThrow("folders",null,v);store.registerDocument(source.getPath(),"QA protected document",1);ContentValues location=new ContentValues();location.put("folder_id",child);store.db().update("docs",location,"path=?",new String[]{source.getPath()});try(Cursor row=store.db().rawQuery("SELECT id FROM docs WHERE path=?",new String[]{source.getPath()})){assertTrue(row.moveToFirst());id=row.getLong(0);}}
        final long parentId=folder;AtomicBoolean configured=new AtomicBoolean();try{inst.runOnMainSync(()->folderCall("configure",a,parentId,()->configured.set(true)));awaitPinDialog(2);inst.runOnMainSync(()->{ArrayList<EditText> edits=edits();assertTrue(edits.size()>=2);edits.get(edits.size()-2).setText("735291");edits.get(edits.size()-1).setText("735291");positive();});waitUntil(configured::get,15000);String encoded=c.getSharedPreferences("folder_locks",0).getString("pin_"+folder,"");assertFalse(encoded.contains("735291"));inst.runOnMainSync(FolderLock::lockAll);try(DocumentStore store=new DocumentStore(c)){assertFalse(FolderLock.allowed(c,store,child));try(Cursor rows=store.db().rawQuery("SELECT id FROM docs WHERE id=? AND "+FolderLock.visibleSql(c,store),new String[]{Long.toString(id)})){assertFalse(rows.moveToFirst());}store.indexText();try(Cursor row=store.db().rawQuery("SELECT search_text,search_meta FROM docs WHERE id=?",new String[]{Long.toString(id)})){assertTrue(row.moveToFirst());assertEquals("",row.getString(0));assertEquals("",row.getString(1));}}
            AtomicBoolean unlocked=new AtomicBoolean();inst.runOnMainSync(()->folderCall("authenticate",a,parentId,()->unlocked.set(true)));awaitPinDialog(1);inst.runOnMainSync(()->{edits().get(edits().size()-1).setText("000000");positive();});waitUntil(()->c.getSharedPreferences("folder_locks",0).getInt("fails_"+parentId,0)>0,15000);assertFalse(unlocked.get());awaitPinDialog(1);inst.runOnMainSync(()->{edits().get(edits().size()-1).setText("735291");positive();});waitUntil(unlocked::get,15000);try(DocumentStore store=new DocumentStore(c)){assertTrue(FolderLock.allowed(c,store,child));}json("folder-lock.json",new JSONObject().put("saltedPin",true).put("wrongPinRejected",true).put("descendantHidden",true).put("indexCleared",true).put("correctPinUnlock",true).put("biometricHardwareTested",false));
        }finally{c.getSharedPreferences("folder_locks",0).edit().remove("pin_"+folder).remove("bio_"+folder).remove("fails_"+folder).remove("wait_"+folder).commit();inst.runOnMainSync(FolderLock::lockAll);try(DocumentStore store=new DocumentStore(c)){store.db().delete("docs","id=?",new String[]{Long.toString(id)});store.db().delete("folders","id IN (?,?)",new String[]{Long.toString(folder),Long.toString(child)});}inst.runOnMainSync(a::finish);}}
